class FileError : public std::exception {
public:
    explicit FileError(std::string filename)
        : m_filename(std::move(filename)) {}

    const char* what() const noexcept override {
        return m_message.c_str();
    }

    virtual const std::string& getFilename() const noexcept {
        return m_filename;
    }

protected:
    virtual void setMessage(std::string message) {
        m_message = std::move(message);
    }

private:
    std::string m_filename;
    std::string m_message;
};

class FileReadError : public FileError {
public:
    FileReadError(std::string filename, std::size_t lineNumber)
        : FileError(std::move(filename)), m_lineNumber(lineNumber) {
        setMessage(std::format("Error reading {}, line {}", getFilename(), lineNumber));
    }

    virtual std::size_t getLineNumber() const noexcept {
        return m_lineNumber;
    }

private:
    std::size_t m_lineNumber{0};
};
